    "contact map",
    "donor-acceptor pair",
    "chirality",
    "fixed-point closure",
    "mechanical stability"
  ],
  "boundary": "The whole-chain atomic conformation operator that contains the local contact-map composition and enforces global mechanical stability via fixed-point closure.",
  "opcodes": {
    "VINIT": {
      "element": "Unfolded polypeptide chain",
      "justification": "The void state before any specific donor-acceptor contact is established or chirality is resolved; the chain exists as a linear sequence without defined tertiary structure."
    },
    "TANCH": {
      "element": "Whole-chain folding operator",
      "justification": "The terminal anchor that defines the closed boundary of the system; it contains all local interactions and enforces the global constraint of mechanical stability."
    },
    "AFWD": {
      "element": "Contact formation",
      "justification": "The forward morphism where local donor-acceptor pairs are composed into the whole-chain structure, propagating constraints from local to global."
    },
    "AREV": {
      "element": "Constraint propagation",
      "justification": "The reverse transformation where global stability requirements descend to constrain local contact geometries, ensuring the local pairs satisfy the global fixed-point condition."
    },
    "CLINK": {
      "element": "Contact map composition",
      "justification": "The sequential chaining of local contact pairs into a coherent global map; each contact is composed with the next to build the full structural network."
    },
    "IMSCRIB": {
      "element": "Chirality identity",
      "justification": "The self-reference of the persistent chirality; the structural handedness is an intrinsic property that remains invariant under the folding process."
    },
    "FSPLIT": {
      "element": "Candidate contact selection",
      "justification": "The split into two arms: one arm selects a valid donor-acceptor pair from the bank, the other arm evaluates the alternative pairs that are rejected or held in reserve."
    },
    "FFUSE": {
      "element": "Contact resolution",
      "justification": "The rejoining of the selected contact and the rejected alternatives into a single resolved state; the selected contact is committed, and the rejected ones are banked as alternatives."
    },
    "EVALT": {
      "element": "Valid contact",
      "justification": "The affirmative state where a donor-acceptor pair satisfies the geometric and matrix relations required for a stable contact."
    },
    "EVALF": {
      "element": "Invalid contact",
      "justification": "The negative state where a donor-acceptor pair fails to satisfy the geometric or matrix relations, leading to rejection."
    },
    "ENGAGR": {
      "element": "Chirality conflict",
      "justification": "The state where both left-handed and right-handed chirality are held simultaneously in the local frame, a contradiction that is kept live without resolution until the global constraint forces a choice."
    },
    "IFIX": {
      "element": "Fixed-point closure",
      "justification": "The irreversible fixation of the final conformation; once the fixed-point is reached, the structure is mechanically stable and cannot be undone without breaking the chain."
    }
  },
  "frobenius": {
    "split_element": "Candidate contact selection",
    "split_input": "Bank of candidate donor-acceptor pairs",
    "split_outputs": [
      "Selected valid contact",
      "Rejected alternative contacts"
    ],
    "fuse_element": "Contact resolution",
    "fuse_result": "Resolved contact state with banked alternatives",
    "rejoin_note": "The selected contact is committed to the global map, while the rejected alternatives are held in the bank; the arms rejoin into a single state where the selected contact is active and the alternatives are preserved."
  },
  "registers": {
    "void": "Unfolded chain with no defined contacts or chirality",
    "true": "Stable contact formed with correct chirality and geometric relations",
    "false": "Invalid contact due to geometric or chirality mismatch",
    "both": "Local frame holding both left and right chirality simultaneously, unresolved"
  },
  "sequence": [
    "VINIT: Initialize the unfolded polypeptide chain as the void state",
    "TANCH: Establish the whole-chain folding operator as the terminal anchor",
    "AFWD: Begin forward composition of local contact pairs into the global map",
    "FSPLIT: Split the bank of candidate donor-acceptor pairs into selected and rejected arms",
    "EVALT: Evaluate the selected arm for valid geometric and matrix relations",
    "EVALF: Evaluate the rejected arm for invalid relations",
    "ENGAGR: Hold the chirality conflict in the local frame if both handedness are present",
    "FFUSE: Rejoin the selected and rejected arms into a resolved contact state",
    "CLINK: Compose the resolved contact with the next contact in the chain",
    "AREV: Propagate global stability constraints back to the local contact frame",
    "IMSCRIB: Assert the chirality identity of the resolved contact",
    "AFWD: Continue forward composition with the next contact pair",
    "FSPLIT: Split the next bank of candidate pairs",
    "EVALT: Evaluate the next selected arm",
    "EVALF: Evaluate the next rejected arm",
    "FFUSE: Rejoin the next resolved contact state",
    "CLINK: Compose the next resolved contact",
    "AREV: Propagate constraints again",
    "IMSCRIB: Assert chirality identity again",
    "IFIX: Fix the final conformation at the fixed-point closure",
    "TANCH: Confirm the whole-chain operator has reached mechanical stability"
  ],
  "m⊙²": {
    "compiler": "The lattice-based constraint solver that translates geometric and matrix relations into contact formation operations",
    "ipc": "The constraint propagation channel that passes global stability requirements to local contact frames and returns local validity to the global map",
    "memory": "The bank of candidate donor-acceptor pairs and the resolved contact map, stored as a persistent structure that retains all alternatives",
    "scheduler": "The sequential composition order that processes contact pairs in the order they appear in the chain, with backtracking allowed for constraint resolution",
    "alfs": "The initial unfolded chain and the set of geometric and matrix relations that define valid contacts"
  },
  "entropy": {
    "cost": "The computational effort to evaluate geometric and matrix relations for each candidate contact pair",
    "pre": "Unfolded chain with a bank of candidate contacts and no resolved structure",
    "post": "Folded chain with a resolved contact map and fixed-point closure",
    "verdict": "ΔS ≈ 0 — The system conserves entropy by retaining all rejected alternatives in the bank and only fixing the selected contacts, ensuring no information is lost during the folding process."
  }
}

